import{S as t,o as n,c as e,a9 as h,B as p}from"./chunks/framework.DxG24V0C.js";const k="/agentsrc/images/opencode/05-subtask-dispatch.svg",l="/agentsrc/images/opencode/05-subagent-isolation.svg",g=JSON.parse('{"title":"OpenCode Agent 系统：SubAgent 的委派、隔离与边界设计","description":"","frontmatter":{"title":"OpenCode Agent 系统：SubAgent 的委派、隔离与边界设计"},"headers":[],"relativePath":"opencode/05-agents.md","filePath":"opencode/05-agents.md","lastUpdated":1788319991000}'),d={name:"opencode/05-agents.md"},c=Object.assign(d,{setup(o){const i=[{question:'OpenCode 的子 agent 权限由 deriveSubagentSessionPermission 派生，其中"默认禁止 task（子不能再次委派）"这一规则主要解决什么问题？',options:["让子 agent 的每次调用都重新申请独立授权","防止子 agent 递归委派生成无限深度的子代理","让子 agent 只能调用固定类型的任务防止操纵","把子 agent 的任务调用限制在单个回合内"],correct:1,explanation:'默认禁 task + 工具层把 task 置 false + 默认 agent 拒绝 subagent 当主，这三层从源头掐死"子 agent 再生子 agent"的递归。这样避免了多 agent 递归爆炸这个复杂度黑洞。'},{question:"OpenCode 用 schema 定义 agent（Mode=subagent/primary/all），Claude Code 用隐式区分。相比隐式，schema 化的核心优势在哪里？",options:["让每个子 agent 在运行时分配独立线程来提升吞吐","让 agent 配置可查询、可注入、可编译期校验","让子 agent 用独立内存加速其单次调用时延","把多个子 agent 在调度层合并成单个 agent 提高并行"],correct:1,explanation:'schema 把"agent 是谁"变成可查询、可 patch 的数据（permission/model/mode/steps），强类型让传错 agent 名编译期暴露，配置可被插件 Immer 编辑。隐式方案（如 CC）拿不到这些工程保障。'},{question:"OpenCode 里子 agent 完成执行后，父 agent 以什么形态收回结果状态与正文？",options:["一个持久的共享引用让父子 agent 双向直接读写","一段带 state 的 XML 工具输出由父 LLM 自行解析","把子 agent stdout 通过日志通道原样转交给父","父 agent 多次轮询子 agent 以后再合并结果"],correct:1,explanation:"结果是统一的 `<task id=.. state=..>` 形态（内容包 task_result）的 XML 工具输出。LLM 从 state 与正文读取任务是否完成、结果是什么，再决定下一步。这是用结构化状态让父整体接管子任务的回路的写照。"},{question:'task 工具把"子 agent 执行"推迟到 runLoop 的下一轮才真正执行，设计意图是什么？',options:["在下一轮给子 agent 分配独立线程以获得并行 compute","先趁早把子 agent 权限校准到主线程避免取消冲突","让 runLoop 主循环保持只轮询 + 分发、不陷入子任务内部","利用局部变量缓存子 agent，以便下一轮直接调度子任务"],correct:2,explanation:'task 只负责先立一个 subtask part 占位、再丢给下一轮 runLoop 从 tasks.pop() 弹出来执行。这样 runLoop 只做"轮询+分发"，重活由 handleSubtask 分支承担，结构保持纯粹。这与第四章压缩的 create/process 两段式同源。'},{question:"OpenCode 调度是串行 tasks.pop()，相对 Claude Code 并行 coordinator，串行的设计侧重是？",options:["串行让子 agent 复用共享的 ProviderId 从而简化凭证管理","串行在产物量固定时可保证中间结果输出时序稳定","串行以一个队列一次弹一个换取实现简单但放弃并行响应","串行依赖子会话唯一 id 而并行必须靠多队列做路由"],correct:2,explanation:'tasks.pop() 单队列一次一个，实现最简单、成本最低，适合线性任务流。代价是放弃并行（多子任务不能同时跑）。CC coordinator 并行更强大更贵。这一对比落在"靠数据结构简单 vs 靠协调复杂度"的取舍上。'}];return(r,s)=>{const a=t("Quiz");return n(),e("div",null,[s[0]||(s[0]=h("",91)),p(a,{questions:i})])}}});export{g as __pageData,c as default};
